class Rva006F7DA0TreeBuffer {
public:
	static UnsignedInt __stdcall doLighting(const GlobalData::TerrainLighting *objectLighting, const Vector3 *emissive,
		UnsignedInt vertDiffuse, Real scale, UnsignedInt alpha);
};

// TheWritableGlobalData view: +0x218 is m_timeOfDay (name_oracle); the
// lighting rows it indexes (0x6c = three TerrainLighting) start at +0x224.
struct Rva006F83F0GlobalDataView {
	char m_unreconstructed_000[0x218];
	Int m_timeOfDay;
	char m_unreconstructed_21c[0x224 - 0x21c];
	GlobalData::TerrainLighting m_lighting224[1][3];
};

// Object at owner+0x28: two floats whose product overrides the owner's alpha.
struct Rva006F83F0Provider {
	char m_unreconstructed_000[0xb0];
	Real m_fieldB0;
	Real m_fieldB4;
	Real getProduct() const { return m_fieldB4 * m_fieldB0; }
};

// MeshModelClass::CurMatDesc sits at +0x9c in BFME (name_oracle); the Zero
// Hour header puts it at +0x98, so the body reads it by offset.

class Rva006F8700Owner {
public:
	int rva006F83F0(void *destination_vb, int curVertex, void *mtx, void *mesh);
private:
	char m_unreconstructed_000[0x28];
	Rva006F83F0Provider *m_field28;
	Vector3 m_field2c;
	char m_unreconstructed_038[0x80 - 0x38];
	Real m_field80;
};

int Rva006F8700Owner::rva006F83F0(void *destination_vb, int curVertex, void *rawMtx, void *rawMesh)
{
	MeshClass *pMesh = (MeshClass *)rawMesh;
	if (pMesh == NULL)
		return(0);
	Real alpha;
	if (m_field28 && m_field28->getProduct() != 1.0f)
		alpha = m_field28->getProduct();
	else
		alpha = m_field80;
	if (alpha < 0.0f)
		alpha = 0.0f;
	else if (alpha > 1.0f)
		alpha = 1.0f;
	UnsignedInt alphaByte = (UnsignedInt)(alpha * 255.0);
	Rva006F83F0GlobalDataView *global = (Rva006F83F0GlobalDataView *)TheWritableGlobalData;
	const GlobalData::TerrainLighting *lighting = global->m_lighting224[global->m_timeOfDay];
	Int numVertex = pMesh->Peek_Model()->Get_Vertex_Count();
	Vector3 *pVert = pMesh->Peek_Model()->Get_Vertex_Array();
	if (curVertex + numVertex + 2 >= 15000)
		return(0);
	Vector3 emissive(0.0f, 0.0f, 0.0f);
	MaterialInfoClass *matInfo = pMesh->Get_Material_Info();
	if (matInfo) {
		VertexMaterialClass *vertMat = matInfo->Peek_Vertex_Material(0);
		if (vertMat)
			vertMat->Get_Emissive(&emissive);
		matInfo->Release_Ref();
	}
	const Vector2 *uvs = (*(MeshMatDescClass **)((char *)pMesh->Peek_Model() + 0x9c))->Get_UV_Array_By_Index(0, false);
	VertexFormatXYZNDUV1 *curVb = (VertexFormatXYZNDUV1 *)destination_vb + curVertex;
	UnsignedInt *colors = (*(MeshMatDescClass **)((char *)pMesh->Peek_Model() + 0x9c))->Get_Color_Array(0, false);
	for (Int i = 0; i < numVertex; ++i) {
		curVb->u1 = uvs[i].U;
		curVb->v1 = uvs[i].V;
		Vector3 vertex;
		Matrix3D::Transform_Vector(*(const Matrix3D *)rawMtx, pVert[i], &vertex);
		Vector3 vLoc;
		vLoc = vertex + m_field2c;
		curVb->x = vLoc.X;
		curVb->y = vLoc.Y;
		curVb->z = vLoc.Z;
		curVb->diffuse = Rva006F7DA0TreeBuffer::doLighting(lighting, &emissive, colors ? colors[i] : 0xffffffff, 1.0f, alphaByte);
		++curVb;
	}
	return(numVertex);
}
